class Solution:
    def maxActivatedPoints(self, points):
        parent = {}
        def find(a):
            parent.setdefault(a, a)
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a
        cx, cy = {}, {}
        for x, y in points:
            cx[x] = cx.get(x, 0) + 1
            cy[y] = cy.get(y, 0) + 1
            rx, ry = find(('r', x)), find(('c', y))
            if rx != ry: parent[ry] = rx
        agg = {}
        for x, y in points:
            r = find(('r', x))
            a = agg.setdefault(r, [0, 0, 0])
            a[0] = max(a[0], cx[x]); a[1] = max(a[1], cy[y]); a[2] += 1
        rows = sorted(((a[0], r) for r, a in agg.items()), reverse=True)
        cols = sorted(((a[1], r) for r, a in agg.items()), reverse=True)
        best = max(a[2] for a in agg.values())
        for r, a in agg.items():
            for v, r2 in rows[:2]:
                if r2 != r: best = max(best, a[0] + v)
            for v, r2 in cols[:2]:
                if r2 != r: best = max(best, a[1] + v)
        return best + 1

