class Solution {
    unordered_map<long long, long long> par;
    long long find(long long a) {
        if (!par.count(a)) par[a] = a;
        while (par[a] != a) { par[a] = par[par[a]]; a = par[a]; }
        return a;
    }
public:
    int maxActivatedPoints(vector<vector<int>>& points) {
        unordered_map<long long, long long> cx, cy;
        for (auto& p : points) {
            cx[p[0]]++; cy[p[1]]++;
            long long rx = find(p[0]), ry = find(~(long long)p[1]);
            if (rx != ry) par[ry] = rx;
        }
        struct A { long long mr = 0, mc = 0, tot = 0; };
        unordered_map<long long, A> agg;
        for (auto& p : points) {
            A& a = agg[find(p[0])];
            a.mr = max(a.mr, cx[p[0]]); a.mc = max(a.mc, cy[p[1]]); a.tot++;
        }
        vector<pair<long long,long long>> rows, cols;
        for (auto& [r, a] : agg) { rows.push_back({a.mr, r}); cols.push_back({a.mc, r}); }
        sort(rows.rbegin(), rows.rend()); sort(cols.rbegin(), cols.rend());
        long long best = 0;
        for (auto& [r, a] : agg) best = max(best, a.tot);
        for (auto& [r, a] : agg) {
            for (int i = 0; i < 2 && i < (int)rows.size(); i++)
                if (rows[i].second != r) best = max(best, a.mr + rows[i].first);
            for (int i = 0; i < 2 && i < (int)cols.size(); i++)
                if (cols[i].second != r) best = max(best, a.mc + cols[i].first);
        }
        return (int)(best + 1);
    }
};

