class Solution {
    private Map<Long, Long> par = new HashMap<>();
    private long find(long a) {
        par.putIfAbsent(a, a);
        while (par.get(a) != a) { par.put(a, par.get(par.get(a))); a = par.get(a); }
        return a;
    }
    public int maxActivatedPoints(int[][] points) {
        Map<Long, Long> cx = new HashMap<>(), cy = new HashMap<>();
        for (int[] p : points) {
            cx.merge((long) p[0], 1L, Long::sum);
            cy.merge((long) p[1], 1L, Long::sum);
            long rx = find(p[0]), ry = find(~(long) p[1]);
            if (rx != ry) par.put(ry, rx);
        }
        Map<Long, long[]> agg = new HashMap<>();
        for (int[] p : points) {
            long[] a = agg.computeIfAbsent(find(p[0]), k -> new long[3]);
            a[0] = Math.max(a[0], cx.get((long) p[0]));
            a[1] = Math.max(a[1], cy.get((long) p[1]));
            a[2]++;
        }
        List<long[]> rows = new ArrayList<>(), cols = new ArrayList<>();
        long best = 0;
        for (var e : agg.entrySet()) {
            rows.add(new long[]{e.getValue()[0], e.getKey()});
            cols.add(new long[]{e.getValue()[1], e.getKey()});
            best = Math.max(best, e.getValue()[2]);
        }
        rows.sort((x, y) -> Long.compare(y[0], x[0]));
        cols.sort((x, y) -> Long.compare(y[0], x[0]));
        for (var e : agg.entrySet()) {
            long r = e.getKey(); long[] a = e.getValue();
            for (int i = 0; i < Math.min(2, rows.size()); i++)
                if (rows.get(i)[1] != r) best = Math.max(best, a[0] + rows.get(i)[0]);
            for (int i = 0; i < Math.min(2, cols.size()); i++)
                if (cols.get(i)[1] != r) best = Math.max(best, a[1] + cols.get(i)[0]);
        }
        return (int) (best + 1);
    }
}

