from collections import defaultdict, deque
class Solution:
    def maxActivatedPoints(self, points):
        n = len(points)
        rowMap = defaultdict(list); colMap = defaultdict(list)
        for i, (x, y) in enumerate(points):
            rowMap[x].append(i); colMap[y].append(i)
        cx = {x: len(v) for x, v in rowMap.items()}
        cy = {y: len(v) for y, v in colMap.items()}
        comp = [-1]*n; info = []
        for s in range(n):
            if comp[s] != -1: continue
            cid = len(info); q = deque([s]); comp[s] = cid
            mr = mc = tot = 0
            while q:
                i = q.popleft(); x, y = points[i]; tot += 1
                mr = max(mr, cx[x]); mc = max(mc, cy[y])
                for j in rowMap[x] + colMap[y]:
                    if comp[j] == -1: comp[j] = cid; q.append(j)
            info.append([mr, mc, tot])
        rows = sorted(((a[0], i) for i, a in enumerate(info)), reverse=True)
        cols = sorted(((a[1], i) for i, a in enumerate(info)), reverse=True)
        best = max(a[2] for a in info)
        for i, a in enumerate(info):
            for v, j in rows[:2]:
                if j != i: best = max(best, a[0] + v)
            for v, j in cols[:2]:
                if j != i: best = max(best, a[1] + v)
        return best + 1

