class Solution {
public:
    int maxActivatedPoints(vector<vector<int>>& points) {
        int n = points.size();
        unordered_map<int, vector<int>> rowMap, colMap;
        for (int i = 0; i < n; i++) { rowMap[points[i][0]].push_back(i); colMap[points[i][1]].push_back(i); }
        unordered_map<int,int> cx, cy;
        for (auto& [x, v] : rowMap) cx[x] = v.size();
        for (auto& [y, v] : colMap) cy[y] = v.size();
        vector<int> comp(n, -1);
        vector<array<long long,3>> info;
        for (int s = 0; s < n; s++) {
            if (comp[s] != -1) continue;
            int cid = info.size(); queue<int> q; q.push(s); comp[s] = cid;
            long long mr = 0, mc = 0, tot = 0;
            while (!q.empty()) {
                int i = q.front(); q.pop();
                int x = points[i][0], y = points[i][1];
                tot++; mr = max(mr, (long long)cx[x]); mc = max(mc, (long long)cy[y]);
                for (int j : rowMap[x]) if (comp[j] == -1) { comp[j] = cid; q.push(j); }
                for (int j : colMap[y]) if (comp[j] == -1) { comp[j] = cid; q.push(j); }
            }
            info.push_back({mr, mc, tot});
        }
        vector<pair<long long,int>> rows, cols;
        for (int i = 0; i < (int)info.size(); i++) { rows.push_back({info[i][0], i}); cols.push_back({info[i][1], i}); }
        sort(rows.rbegin(), rows.rend()); sort(cols.rbegin(), cols.rend());
        long long best = 0;
        for (auto& a : info) best = max(best, a[2]);
        for (int i = 0; i < (int)info.size(); i++) {
            for (int k = 0; k < 2 && k < (int)rows.size(); k++)
                if (rows[k].second != i) best = max(best, info[i][0] + rows[k].first);
            for (int k = 0; k < 2 && k < (int)cols.size(); k++)
                if (cols[k].second != i) best = max(best, info[i][1] + cols[k].first);
        }
        return (int)(best + 1);
    }
};

