class Solution {
    public int maxActivatedPoints(int[][] points) {
        int n = points.length;
        Map<Integer, List<Integer>> rowMap = new HashMap<>(), colMap = new HashMap<>();
        for (int i = 0; i < n; i++) {
            rowMap.computeIfAbsent(points[i][0], k -> new ArrayList<>()).add(i);
            colMap.computeIfAbsent(points[i][1], k -> new ArrayList<>()).add(i);
        }
        Map<Integer, Integer> cx = new HashMap<>(), cy = new HashMap<>();
        rowMap.forEach((k, v) -> cx.put(k, v.size()));
        colMap.forEach((k, v) -> cy.put(k, v.size()));
        int[] comp = new int[n]; Arrays.fill(comp, -1);
        List<long[]> info = new ArrayList<>();
        for (int s = 0; s < n; s++) {
            if (comp[s] != -1) continue;
            int cid = info.size(); Deque<Integer> q = new ArrayDeque<>(); q.add(s); comp[s] = cid;
            long mr = 0, mc = 0, tot = 0;
            while (!q.isEmpty()) {
                int i = q.poll(); int x = points[i][0], y = points[i][1];
                tot++; mr = Math.max(mr, cx.get(x)); mc = Math.max(mc, cy.get(y));
                for (int j : rowMap.get(x)) if (comp[j] == -1) { comp[j] = cid; q.add(j); }
                for (int j : colMap.get(y)) if (comp[j] == -1) { comp[j] = cid; q.add(j); }
            }
            info.add(new long[]{mr, mc, tot});
        }
        List<long[]> rows = new ArrayList<>(), cols = new ArrayList<>();
        for (int i = 0; i < info.size(); i++) { rows.add(new long[]{info.get(i)[0], i}); cols.add(new long[]{info.get(i)[1], i}); }
        rows.sort((a, b) -> Long.compare(b[0], a[0])); cols.sort((a, b) -> Long.compare(b[0], a[0]));
        long best = 0;
        for (long[] a : info) best = Math.max(best, a[2]);
        for (int i = 0; i < info.size(); i++) {
            for (int k = 0; k < Math.min(2, rows.size()); k++)
                if (rows.get(k)[1] != i) best = Math.max(best, info.get(i)[0] + rows.get(k)[0]);
            for (int k = 0; k < Math.min(2, cols.size()); k++)
                if (cols.get(k)[1] != i) best = Math.max(best, info.get(i)[1] + cols.get(k)[0]);
        }
        return (int) (best + 1);
    }
}

