var maxActivatedPoints = function(points) {
    const n = points.length;
    const rowMap = new Map(), colMap = new Map();
    for (let i = 0; i < n; i++) {
        if (!rowMap.has(points[i][0])) rowMap.set(points[i][0], []);
        if (!colMap.has(points[i][1])) colMap.set(points[i][1], []);
        rowMap.get(points[i][0]).push(i); colMap.get(points[i][1]).push(i);
    }
    const cx = new Map([...rowMap].map(([k, v]) => [k, v.length]));
    const cy = new Map([...colMap].map(([k, v]) => [k, v.length]));
    const comp = new Array(n).fill(-1); const info = [];
    for (let s = 0; s < n; s++) {
        if (comp[s] !== -1) continue;
        const cid = info.length; const q = [s]; comp[s] = cid;
        let mr = 0, mc = 0, tot = 0;
        while (q.length) {
            const i = q.shift(); const [x, y] = points[i];
            tot++; mr = Math.max(mr, cx.get(x)); mc = Math.max(mc, cy.get(y));
            for (const j of [...rowMap.get(x), ...colMap.get(y)])
                if (comp[j] === -1) { comp[j] = cid; q.push(j); }
        }
        info.push([mr, mc, tot]);
    }
    const rows = info.map((a, i) => [a[0], i]).sort((a, b) => b[0] - a[0]);
    const cols = info.map((a, i) => [a[1], i]).sort((a, b) => b[0] - a[0]);
    let best = 0;
    for (const a of info) best = Math.max(best, a[2]);
    info.forEach((a, i) => {
        for (let k = 0; k < Math.min(2, rows.length); k++)
            if (rows[k][1] !== i) best = Math.max(best, a[0] + rows[k][0]);
        for (let k = 0; k < Math.min(2, cols.length); k++)
            if (cols[k][1] !== i) best = Math.max(best, a[1] + cols[k][0]);
    });
    return best + 1;
};
